mapper.sql:
WHERE status = 'onswap'
AND tenant_id = #{tenantId}
AND cat_l1 = #{catL1}
AND condition_level = #{conditionLevel}

    AND (delivery_mode = #{deliveryMode} OR delivery_mode = 'both')


    AND MATCH(title, description) AGAINST(#{keyword} IN NATURAL LANGUAGE MODE)

mapper.select:
SELECT 
FROM twelve_exchange_item
WHERE id = #{itemId}
AND tenant_id = #{tenantId}

mapper.update:
UPDATE twelve_exchange_item
SET view_count = view_count + 1, hot_score = hot_score + 1, update_time = NOW()
WHERE id = #{itemId}
AND tenant_id = #{tenantId}

UPDATE twelve_exchange_item
SET offer_count = offer_count + 1, hot_score = hot_score + 3, update_time = NOW()
WHERE id = #{itemId}
AND tenant_id = #{tenantId}

mapper.select:
SELECT 
FROM twelve_exchange_item
WHERE owner_id = #{ownerId}
AND tenant_id = #{tenantId}
AND status = #{status}
ORDER BY create_time DESC
LIMIT #{limit}

mapper.update:
UPDATE twelve_exchange_item
SET status = #{toStatus}, update_time = NOW()
WHERE id = #{itemId} AND owner_id = #{ownerId} AND status = #{fromStatus}
AND tenant_id = #{tenantId}

mapper.select:
SELECT COALESCE(SUM(swap_count), 0)
FROM twelve_exchange_item
WHERE owner_id = #{ownerId}
AND tenant_id = #{tenantId}
